class File{std::shared_ptr<Bytes> b;size_t at=0;bool writing=false;public:File(){}File(std::shared_ptr<Bytes> x,bool w):b(x),writing(w){if(w)b->clear();}operator bool()const{return bool(b);}bool isDirectory(){return false;}size_t size(){return b?b->size():0;}size_t read(uint8_t*out,size_t n){if(!b)return 0;n=std::min(n,b->size()-at);memcpy(out,b->data()+at,n);at+=n;if(corruptRead&&n)out[0]^=1;return n;}size_t write(const uint8_t*p,size_t n){if(!b||writeFail)return 0;b->insert(b->end(),p,p+n);return n;}void flush(){}void close(){b.reset();}};
static struct FS{File open(const char*p,const char*mode=nullptr){auto i=files.find(p);if(mode){if(i==files.end())i=files.emplace(p,std::make_shared<Bytes>()).first;return File(i->second,true);}return i==files.end()?File():File(i->second,false);}bool exists(const char*p){return files.count(p)||std::string(p)=="/System/mesh";}bool mkdir(const char*){return true;}bool remove(const char*p){if(removeFail)return false;return files.erase(p)>0;}bool rename(const char*a,const char*b){if(renameFail)return false;auto i=files.find(a);if(i==files.end())return false;files[b]=i->second;files.erase(i);return true;}}tab5FS;
