 M::Preferences p,p2;p.options={true,true,true};p.knownCount=8;p.preferred=7;for(unsigned i=0;i<8;++i){p.known[i].address[0]=i;p.known[i].type=i%4;p.known[i].unpaired=i%2;snprintf(p.known[i].name,40,"Radio %u",i);}check(Tab5MeshStore::savePreferences(p)&&Tab5MeshStore::loadPreferences(p2)&&p2.options.background&&p2.knownCount==8&&p2.preferred==7,"NVS options and addresses roundtrip");nvs[5]^=1;check(!Tab5MeshStore::loadPreferences(p2),"NVS CRC rejects damaged preferences");
